[{"order":1,"type":"heading","text":"Firestore Security Rules Language Syntax"},{"order":2,"type":"paragraph","text":"Cloud Firestore Security Rules control access to documents and collections in your database. The rules language resembles JavaScript in its expression syntax, but it has a specific grammar designed for routing, authorization, and evaluating hierarchical data structures."},{"order":3,"type":"subheading","text":"Basic Structure of a Rules File"},{"order":4,"type":"paragraph","text":"Every rules file starts with a version declaration, followed by the service definition, and then one or more match blocks that target specific paths in your Firestore database."},{"order":5,"type":"code","text":"rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    // Rules go here
  }
}"},{"order":6,"type":"subheading","text":"Path Matching and Wildcards"},{"order":7,"type":"paragraph","text":"Path matching allows you to apply rules to specific collections or documents. You can use wildcards to capture dynamic segments of a path, such as document IDs."},{"order":8,"type":"code","text":"match /users/{userId} {
  allow read, write: if request.auth != null && request.auth.uid == userId;
}"},{"order":9,"type":"bullet_point","text":"Single segment wildcards like {userId} match a single document ID within a collection."},{"order":10,"type":"bullet_point","text":"Recursive wildcards like {document=**} match any number of nested subcollections and documents."},{"order":11,"type":"subheading","text":"Operations and Allow Statements"},{"order":12,"type":"paragraph","text":"An allow statement grants specific types of access if the accompanying boolean condition evaluates to true. If no conditions evaluate to true, access is denied by default."},{"order":13,"type":"code","text":"match /posts/{postId} {
  allow get: if request.auth != null;
  allow list: if true;
  allow create: if request.auth != null && request.resource.data.authorId == request.auth.uid;
  allow update: if request.auth != null && resource.data.authorId == request.auth.uid;
  allow delete: if request.auth != null && resource.data.authorId == request.auth.uid;
}"},{"order":14,"type":"bullet_point","text":"read: Encompasses both get (single document read) and list (query/collection read)."},{"order":15,"type":"bullet_point","text":"write: Encompasses create, update, and delete operations."},{"order":16,"type":"subheading","text":"Request and Resource Variables"},{"order":17,"type":"paragraph","text":"Rules rely heavily on the request and resource variables to evaluate incoming data against existing data."},{"order":18,"type":"bullet_point","text":"request: Contains metadata about the incoming operation, including request.auth (authentication details), request.time, and request.resource (the new data intended to be written)."},{"order":19,"type":"bullet_point","text":"resource: Represents the existing document in the database prior to the operation, accessed via resource.data.field."},{"order":20,"type":"subheading","text":"Functions and Modular Rules"},{"order":21,"type":"paragraph","text":"To keep your rules maintainable and DRY (Don't Repeat Yourself), you can define custom functions within your security rules file."},{"order":22,"type":"code","text":"service cloud.firestore {
  match /databases/{database}/documents {
    function isSignedIn() {
      return request.auth != null;
    }

    function isOwner(userId) {
      return isSignedIn() && request.auth.uid == userId;
    }

    match /profiles/{userId} {
      allow read, write: if isOwner(userId);
    }
  }
}"}]
